package com.bank.coupling.tight;

import com.bank.coupling.loose.SmsNotificationService;
import com.bank.coupling.model.Trade;

public class TightTradeService {
    // HARDWIRED: directly creates concrete dependencies
    private final SmsNotificationService smsService = new SmsNotificationService();

    public String executeTrade(Trade trade) {
        // LOCKED to SmsService — can't swap to Email without modifying this class!
        return smsService.send(trade.accountId(), "Trade " + trade.tradeId() + " executed");
    }
    // Can't test without SmsService. Can't switch to Email. Tight coupling!
}
