// (Recommended) LOOSELY COUPLED — depends on interfaces, injected
package com.bank.coupling.loose;

import com.bank.coupling.model.Trade;

public class TradeService {
    private final NotificationService notifier;  // INTERFACE!
    private final TradeRepository tradeRepo;      // INTERFACE!

    // Constructor injection — caller decides which implementation
    public TradeService(NotificationService notifier, TradeRepository tradeRepo) {
        this.notifier = notifier;
        this.tradeRepo = tradeRepo;
    }

    public String executeTrade(Trade trade) {
        tradeRepo.save(trade);
        return notifier.send(trade.accountId(), "Trade " + trade.tradeId() + " executed");
    }
}
