// ─── File: src/test/java/com/bank/coupling/CouplingTest.java ───
package com.bank.coupling;

import com.bank.coupling.loose.*;
import com.bank.coupling.model.Trade;
import com.bank.coupling.tight.TightTradeService;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class CouplingTest {

    Trade trade = new Trade("TRD-001", "SAV2001", "RELIANCE", new BigDecimal("245050"));

    // ═══ TIGHT: works but inflexible ═══
    @Test
    void tight_lockedToSms() {
        TightTradeService service = new TightTradeService();
        String result = service.executeTrade(trade);
        assertThat(result).contains("SMS");  // always SMS — can't change!
    }

    // ═══ LOOSE: swap SMS → Email without code change ═══
    @Test
    void loose_smsImplementation() {
        TradeService service = new TradeService(new SmsNotificationService(), mock(TradeRepository.class));
        assertThat(service.executeTrade(trade)).contains("SMS");
    }

    @Test
    void loose_emailImplementation_zeroCodeChange() {
        TradeService service = new TradeService(new EmailNotificationService(), mock(TradeRepository.class));
        assertThat(service.executeTrade(trade)).contains("Email");
        // SAME TradeService. DIFFERENT notification. ZERO code changes!
    }

    // ═══ LOOSE: test with mock — no real SMS/DB ═══
    @Test
    void loose_testWithMock_noRealSms() {
        NotificationService mockNotifier = mock(NotificationService.class);
        TradeRepository mockRepo = mock(TradeRepository.class);
        when(mockNotifier.send(anyString(), anyString())).thenReturn("MOCK: sent");

        TradeService service = new TradeService(mockNotifier, mockRepo);
        String result = service.executeTrade(trade);

        assertThat(result).isEqualTo("MOCK: sent");
        verify(mockNotifier).send("SAV2001", "Trade TRD-001 executed");
        verify(mockRepo).save(trade);
        // No real SMS sent! No real database! Test in 10ms!
    }

    // ═══ LOOSE: add new implementation — zero changes to TradeService ═══
    @Test
    void loose_newPushNotificationService() {
        NotificationService pushService = (accountId, msg) -> "PUSH to " + accountId + ": " + msg;
        TradeService service = new TradeService(pushService, mock(TradeRepository.class));
        assertThat(service.executeTrade(trade)).contains("PUSH");
        // New implementation added as a LAMBDA — TradeService unchanged!
    }
}
```
